schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/growth-experiment-design.json",
  "title": "Growth Experiment Design spec",
  "type": "object",
  "required": ["experiment_id", "hypothesis", "guardrails", "ice", "sample_size", "assignment", "instrumentation", "schedule", "srm_check", "status", "write_up", "counts_toward_velocity"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "event_name": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "score": {"type": "integer", "minimum": 1, "maximum": 10},
    "pct": {"type": "number"}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "experiment_id": {"type": "string", "pattern": "^exp-[a-z0-9]+(-[a-z0-9]+)*$"},
    "hypothesis": {
      "type": "object",
      "required": ["change", "segment", "primary_metric", "minimum_effect_pct", "mechanism"],
      "additionalProperties": false,
      "properties": {
        "change": {"type": "string", "minLength": 10},
        "segment": {"type": "string", "minLength": 3},
        "primary_metric": {"type": "string", "minLength": 3, "not": {"enum": ["engagement", "activation", "growth", "usage", "satisfaction"]}},
        "minimum_effect_pct": {"type": "number", "exclusiveMinimum": 0},
        "mechanism": {"type": "string", "minLength": 15}
      }
    },
    "guardrails": {
      "type": "array",
      "minItems": 3,
      "items": {
        "type": "object",
        "required": ["name", "category", "stop_threshold"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 3},
          "category": {"type": "string", "enum": ["revenue_or_conversion", "retention", "performance_or_error"]},
          "stop_threshold": {"type": "string", "minLength": 3}
        }
      }
    },
    "ice": {
      "type": "object",
      "required": ["impact", "confidence", "ease", "criteria_ref", "confidence_evidence", "backlog_rank"],
      "additionalProperties": false,
      "properties": {
        "impact": {"$ref": "#/definitions/score"},
        "confidence": {"$ref": "#/definitions/score"},
        "ease": {"$ref": "#/definitions/score"},
        "criteria_ref": {"type": "string", "minLength": 3},
        "confidence_evidence": {"type": ["string", "null"], "minLength": 10},
        "backlog_rank": {"type": "integer", "minimum": 1}
      },
      "if": {"properties": {"confidence": {"minimum": 4}}},
      "then": {"properties": {"confidence_evidence": {"type": "string"}}}
    },
    "sample_size": {
      "type": "object",
      "required": ["baseline_rate", "minimum_detectable_effect_pct", "alpha", "power", "required_per_variant", "eligible_daily_traffic", "duration_weeks"],
      "additionalProperties": false,
      "properties": {
        "baseline_rate": {"type": "number", "exclusiveMinimum": 0, "exclusiveMaximum": 1},
        "minimum_detectable_effect_pct": {"type": "number", "exclusiveMinimum": 0},
        "alpha": {"const": 0.05},
        "power": {"const": 0.8},
        "required_per_variant": {"type": "integer", "minimum": 1},
        "eligible_daily_traffic": {"type": "integer", "minimum": 1},
        "duration_weeks": {"type": "integer", "minimum": 1, "maximum": 8}
      }
    },
    "assignment": {
      "type": "object",
      "required": ["platform", "design", "hash_key", "control_variant", "allocation"],
      "additionalProperties": false,
      "properties": {
        "platform": {"type": "string", "enum": ["launchdarkly", "statsig", "unleash", "growthbook", "optimizely", "internal"]},
        "design": {"const": "randomised_controlled"},
        "hash_key": {"type": "string", "enum": ["user_id", "account_id"]},
        "control_variant": {"type": "string", "minLength": 1},
        "allocation": {
          "type": "array",
          "minItems": 2,
          "items": {
            "type": "object",
            "required": ["variant", "percent"],
            "additionalProperties": false,
            "properties": {
              "variant": {"type": "string", "minLength": 1},
              "percent": {"type": "number", "exclusiveMinimum": 0, "maximum": 100}
            }
          }
        }
      }
    },
    "instrumentation": {
      "type": "object",
      "required": ["exposure_event", "exposure_logged_at", "analytics_destination", "metric_events", "playback"],
      "additionalProperties": false,
      "properties": {
        "exposure_event": {"$ref": "#/definitions/event_name"},
        "exposure_logged_at": {"const": "variant_seen"},
        "analytics_destination": {"type": "string", "minLength": 3},
        "metric_events": {"type": "array", "minItems": 1, "items": {"$ref": "#/definitions/event_name"}},
        "playback": {
          "type": "object",
          "required": ["cohort", "status", "performed_on", "events_verified"],
          "additionalProperties": false,
          "properties": {
            "cohort": {"type": "string", "enum": ["staging", "one_percent"]},
            "status": {"type": "string", "enum": ["pending", "passed"]},
            "performed_on": {"anyOf": [{"$ref": "#/definitions/date"}, {"type": "null"}]},
            "events_verified": {"type": "array", "items": {"$ref": "#/definitions/event_name"}}
          }
        }
      }
    },
    "schedule": {
      "type": "object",
      "required": ["launch_date", "stop_date", "sequential_method"],
      "additionalProperties": false,
      "properties": {
        "launch_date": {"$ref": "#/definitions/date"},
        "stop_date": {"$ref": "#/definitions/date"},
        "sequential_method": {"type": ["string", "null"], "minLength": 3}
      }
    },
    "srm_check": {
      "type": "object",
      "required": ["status", "chi_square_p", "invalidates_below"],
      "additionalProperties": false,
      "properties": {
        "status": {"type": "string", "enum": ["pending", "passed", "failed"]},
        "chi_square_p": {"type": ["number", "null"], "minimum": 0, "maximum": 1},
        "invalidates_below": {"const": 0.001}
      },
      "if": {"properties": {"status": {"enum": ["passed", "failed"]}}},
      "then": {"properties": {"chi_square_p": {"type": "number"}}}
    },
    "status": {"type": "string", "enum": ["designed", "playback_passed", "running", "stopped", "written_up"]},
    "write_up": {
      "anyOf": [
        {"type": "null"},
        {
          "type": "object",
          "required": ["date", "log_entry", "decision", "primary_effect", "guardrail_results", "srm_p", "belief_changed"],
          "additionalProperties": false,
          "properties": {
            "date": {"$ref": "#/definitions/date"},
            "log_entry": {"type": "string", "minLength": 3},
            "decision": {"type": "string", "enum": ["ship", "iterate", "kill"]},
            "primary_effect": {
              "type": "object",
              "required": ["observed_pct", "ci_low_pct", "ci_high_pct"],
              "additionalProperties": false,
              "properties": {
                "observed_pct": {"type": "number"},
                "ci_low_pct": {"type": "number"},
                "ci_high_pct": {"type": "number"}
              }
            },
            "guardrail_results": {
              "type": "array",
              "minItems": 3,
              "items": {
                "type": "object",
                "required": ["name", "observed", "breached"],
                "additionalProperties": false,
                "properties": {
                  "name": {"type": "string", "minLength": 3},
                  "observed": {"type": "string", "minLength": 1},
                  "breached": {"type": "boolean"}
                }
              }
            },
            "srm_p": {"type": "number", "minimum": 0, "maximum": 1},
            "belief_changed": {"type": "string", "minLength": 20}
          }
        }
      ]
    },
    "counts_toward_velocity": {"type": "boolean"}
  }
}

output-contract.example:
{
  "experiment_id": "exp-checkout-trust-badges",
  "hypothesis": {
    "change": "show payment-provider trust badges under the card form",
    "segment": "first-time buyers on web checkout",
    "primary_metric": "checkout_to_paid conversion rate",
    "minimum_effect_pct": 5,
    "mechanism": "first-time buyers abandon at the card form because they doubt the payment is secure"
  },
  "guardrails": [
    {"name": "average order value", "category": "revenue_or_conversion", "stop_threshold": "drop of 3 percent or more versus control"},
    {"name": "30-day repeat purchase rate", "category": "retention", "stop_threshold": "drop of 2 points or more versus control"},
    {"name": "checkout page p95 load time", "category": "performance_or_error", "stop_threshold": "above 2.5 s or error rate above 0.5 percent"}
  ],
  "ice": {
    "impact": 7,
    "confidence": 6,
    "ease": 8,
    "criteria_ref": "growth/ice-criteria.md",
    "confidence_evidence": "exp-checkout-copy-2025q4 moved the same step by 3 percent; 14 of 20 exit-survey answers cite payment security",
    "backlog_rank": 2
  },
  "sample_size": {
    "baseline_rate": 0.042,
    "minimum_detectable_effect_pct": 5,
    "alpha": 0.05,
    "power": 0.8,
    "required_per_variant": 143000,
    "eligible_daily_traffic": 15000,
    "duration_weeks": 3
  },
  "assignment": {
    "platform": "statsig",
    "design": "randomised_controlled",
    "hash_key": "user_id",
    "control_variant": "control",
    "allocation": [
      {"variant": "control", "percent": 50},
      {"variant": "trust_badges", "percent": 50}
    ]
  },
  "instrumentation": {
    "exposure_event": "checkout_card_form_viewed",
    "exposure_logged_at": "variant_seen",
    "analytics_destination": "BigQuery dataset analytics.events",
    "metric_events": ["order_paid", "order_paid_value", "repeat_order_paid", "checkout_page_timing", "checkout_error"],
    "playback": {
      "cohort": "one_percent",
      "status": "passed",
      "performed_on": "2026-03-02",
      "events_verified": ["checkout_card_form_viewed", "order_paid", "order_paid_value", "repeat_order_paid", "checkout_page_timing", "checkout_error"]
    }
  },
  "schedule": {
    "launch_date": "2026-03-04",
    "stop_date": "2026-03-25",
    "sequential_method": null
  },
  "srm_check": {
    "status": "passed",
    "chi_square_p": 0.41,
    "invalidates_below": 0.001
  },
  "status": "written_up",
  "write_up": {
    "date": "2026-03-30",
    "log_entry": "growth/experiment-log.md#exp-checkout-trust-badges",
    "decision": "ship",
    "primary_effect": {"observed_pct": 6.8, "ci_low_pct": 1.9, "ci_high_pct": 11.7},
    "guardrail_results": [
      {"name": "average order value", "observed": "+0.4 percent", "breached": false},
      {"name": "30-day repeat purchase rate", "observed": "-0.3 points", "breached": false},
      {"name": "checkout page p95 load time", "observed": "1.9 s, error rate 0.2 percent", "breached": false}
    ],
    "srm_p": 0.41,
    "belief_changed": "Payment-security doubt, not price, is the main reason first-time buyers leave the card form."
  },
  "counts_toward_velocity": true
}

{
  "experiment_id": "exp-new-onboarding",
  "hypothesis": {
    "change": "launch the redesigned onboarding flow",
    "segment": "all new users",
    "primary_metric": "engagement",
    "minimum_effect_pct": 0,
    "mechanism": "a better onboarding will make users more engaged"
  },
  "guardrails": [
    {"name": "support tickets", "category": "performance_or_error", "stop_threshold": "noticeable increase"}
